    if (!view || status !== "Open") return;
    const { viewport, zoom } = view;
    send(BOARD_KEY, "View", viewCodec.encode({ ...viewport, zoom }));
  };

  const loadCached = (): void => {
    const target = view;
    if (!target) return;
    withCache(async (cache) => {
