:root {
  --paper: #fbfaf7;
  --panel: #ffffffee;
  --ink: #1f2328;
  --line: #d9d6cf;
  --accent: #0090ff;
  color-scheme: only light;
}

html,
body,
#app {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
  background: var(--paper);
  color: var(--ink);
  font-family: system-ui, sans-serif;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
}

.board {
  position: fixed;
  inset: 0;
}

.surface {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: crosshair;
}

.surface.panning {
  cursor: grab;
}

.surface.selecting {
  cursor: default;
}

.surface.erasing {
  cursor: cell;
}

.toolbar {
  position: fixed;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel);
  box-shadow: 0 2px 8px #0000001a;
}

.group {
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
  display: flex;
  gap: 4px;
}

.tool {
  display: grid;
  place-items: center;
  width: 36px;

