const covers = (range: LevelRange, key: string): boolean => {
  const [level, tx, ty] = key.split(":").map(Number);
  return (
    range.level === level &&
    tx !== undefined &&
    ty !== undefined &&
    tx >= range.minTx &&
    tx <= range.maxTx &&
    ty >= range.minTy &&
    ty <= range.maxTy
