import { writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { homedir } from "node:os";
import { chromium, devices } from "playwright";
import { createServer } from "vite";

const PORT = 5199;
const OUT = join(homedir(), "development", ".tmp", "stallion-undo");
mkdirSync(OUT, { recursive: true });
const root = new URL("../apps/web/", import.meta.url).pathname;
const server = await createServer({
  root,
  configFile: join(root, "vite.config.ts"),
  server: { host: "0.0.0.0", port: PORT, strictPort: true, hmr: false },
  logLevel: "warn",
});
await server.listen();
const base = process.argv[2] ?? `http://100.104.44.51:${PORT}`;
const browser = await chromium.launch({ headless: true });
const failures = [];
let errorCount = 0;

const path = (cx, cy) =>
  Array.from({ length: 20 }, (_, i) => ({ x: cx - 100 + (i / 19) * 200, y: cy + Math.sin((i / 19) * Math.PI * 2) * 30 }));

const draw = async (page, points) => {
  const cdp = await page.context().newCDPSession(page);
  const touch = (type, p) =>
    cdp.send("Input.dispatchTouchEvent", { type, touchPoints: p ? [{ x: p.x, y: p.y, id: 1, radiusX: 2, radiusY: 2 }] : [] });
  await touch("touchStart", points[0]);
  for (const p of points.slice(1)) await touch("touchMove", p);
  await touch("touchEnd");
  await cdp.detach();
};

const ink = async (page, clip) => {
  const buf = await page.screenshot({ clip });
  return page.evaluate(async (b64) => {
    const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
    const bmp = await createImageBitmap(new Blob([bytes], { type: "image/png" }));
    const c = new OffscreenCanvas(bmp.width, bmp.height);
    const ctx = c.getContext("2d");
    ctx.drawImage(bmp, 0, 0);
    const d = ctx.getImageData(0, 0, bmp.width, bmp.height).data;
    let dark = 0;
    for (let i = 0; i < d.length; i += 4) if (d[i] + d[i + 1] + d[i + 2] < 600) dark++;
    return dark / (d.length / 4);
  }, buf.toString("base64"));
};

for (const scheme of ["light", "dark"]) {
  const context = await browser.newContext({ ...devices["Galaxy Tab S9"], colorScheme: scheme });
  const page = await context.newPage();
  const errors = [];
  page.on("console", (m) => {
    if (m.type() !== "error") return;
    if (/favicon/.test(m.location().url ?? "") || /favicon/.test(m.text())) return;
    errors.push(m.text());
  });
  page.on("pageerror", (e) => errors.push(e.message));
  const url = `${base}/b/undo-${scheme}-${Date.now()}`;
  await page.goto(url, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 30000 });
  await page.waitForTimeout(800);
  const vp = page.viewportSize();
  const a = path(vp.width * 0.35, vp.height * 0.5);
  const b = path(vp.width * 0.65, vp.height * 0.7);
  const clip = (pts) => ({ x: pts[0].x - 20, y: pts[0].y - 50, width: 240, height: 100 });
  const state = async (label) => {
    const s = {
      label,
      a: Number((await ink(page, clip(a))).toFixed(3)),
      b: Number((await ink(page, clip(b))).toFixed(3)),
      undo: await page.getByRole("button", { name: "Undo" }).isEnabled(),
      redo: await page.getByRole("button", { name: "Redo" }).isEnabled(),
    };
    writeFileSync(join(OUT, `${scheme}-${label}.png`), await page.screenshot());
    return s;
  };
  const expect = (s, a1, b1, undo, redo) => {
    const ok = s.a > 0.01 === a1 && s.b > 0.01 === b1 && s.undo === undo && s.redo === redo;
    if (!ok) failures.push(`${scheme} ${s.label}: ${JSON.stringify(s)}`);
    console.log(`${ok ? "ok  " : "FAIL"} ${scheme} ${JSON.stringify(s)}`);
  };
  expect(await state("0-blank"), false, false, false, false);
  await draw(page, a);
  await page.waitForTimeout(300);
  await draw(page, b);
  await page.waitForTimeout(500);
  expect(await state("1-two-strokes"), true, true, true, false);
  await page.getByRole("button", { name: "Undo" }).click();
  await page.waitForTimeout(300);
  expect(await state("2-undo-once"), true, false, true, true);
  await page.getByRole("button", { name: "Undo" }).click();
  await page.waitForTimeout(300);
  expect(await state("3-undo-twice"), false, false, false, true);
  await page.getByRole("button", { name: "Redo" }).click();
  await page.waitForTimeout(300);
  expect(await state("4-redo"), true, false, true, true);
  await page.keyboard.press("Control+z");
  await page.waitForTimeout(200);
  await page.keyboard.press("Control+Shift+z");
  await page.waitForTimeout(800);
  expect(await state("5-keys"), true, false, true, true);
  await page.reload({ waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible" });
  await page.waitForTimeout(1500);
  expect(await state("6-reloaded"), true, false, false, false);
  console.log(`${scheme}: console errors ${errors.length}${errors.length ? `: ${errors.join(" | ")}` : ""}`);
  errorCount += errors.length;
  await context.close();
}
await browser.close();
await server.close();
console.log(failures.length === 0 && errorCount === 0 ? "UNDO CHECK PASSED" : `UNDO CHECK FAILED: ${failures.length} failures, ${errorCount} errors`);
process.exit(failures.length === 0 && errorCount === 0 ? 0 : 1);
EOF
cd ~/development/stallion-worktrees/undo && timeout 300 node .tmp/undo-check.mjs 2>&1 | tail -25

